namespace sv_f949c968ec9c4e0d90fcbbb818e6aa5c.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors =
    [
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Patel",
        "Dr. Lee"
    ];

    private static readonly Dictionary<string, List<string>> DoctorSlots = new()
    {
        ["Dr. Smith"] = ["9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM"],
        ["Dr. Johnson"] = ["8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM"],
        ["Dr. Patel"] = ["9:30 AM", "10:00 AM", "11:30 AM", "2:30 PM"],
        ["Dr. Lee"] = ["8:30 AM", "10:00 AM", "12:00 PM", "3:30 PM"],
    };

    public Task<List<string>> GetDoctorsAsync()
        => Task.FromResult(Doctors);

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        var slots = DoctorSlots.GetValueOrDefault(doctor, []);
        return Task.FromResult(slots);
    }

    /// <summary>
    /// Validates patient + appointment details server-side.
    /// Returns a dictionary of field name → error message for any failures.
    /// An empty dictionary means validation passed.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        // Outstanding balance check
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(BookAppointmentModel.Email)] = "Account has outstanding balance";
        }

        // Self-pay restriction
        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors[nameof(BookAppointmentModel.Doctor)] =
                "Selected doctor does not accept self-pay patients";
        }

        // Slot race-condition check
        if (timeSlot == "10:00 AM")
        {
            errors[nameof(BookAppointmentModel.TimeSlot)] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

public class BookAppointmentModel
{
    // Step 1
    public string PatientName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string InsuranceProvider { get; set; } = "";

    // Step 2
    public string Doctor { get; set; } = "";
    public DateOnly? AppointmentDate { get; set; }
    public string TimeSlot { get; set; } = "";
    public string ReasonForVisit { get; set; } = "";
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_f949c968ec9c4e0d90fcbbb818e6aa5c.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book a Medical Appointment</h3>

<EditForm EditContext="editContext" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    @* ───── STEP 1 ───── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>
    </fieldset>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
            Next
        </button>
    }

    @* ───── STEP 2 ───── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select"
                             @bind-Value="Model.Doctor"
                             @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="appointmentDate">Date</label>
                <InputDate id="appointmentDate" class="form-control"
                           @bind-Value="Model.AppointmentDate"
                           @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3"
                               @bind-Value="Model.ReasonForVisit" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <div class="d-flex gap-2">
                <button type="button" class="btn btn-secondary" @onclick="BackToStep1">
                    Back
                </button>
                <button type="button" class="btn btn-info" @onclick="CheckAvailability">
                    Check Availability
                </button>
                <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked)">
                    Book Appointment
                </button>
            </div>
        </fieldset>
    }
</EditForm>

@if (submitted)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully!
    </div>
}

@code {
    private BookAppointmentModel Model { get; set; } = new();
    private EditContext editContext = default!;
    private ValidationMessageStore messageStore = default!;

    private bool showStep2;
    private bool availabilityChecked;
    private bool submitted;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        messageStore = new ValidationMessageStore(editContext);
        editContext.OnFieldChanged += (_, args) =>
        {
            messageStore.Clear(args.FieldIdentifier);
            availabilityChecked = false;
        };

        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        messageStore.Clear();

        var valid = true;

        if (string.IsNullOrWhiteSpace(Model.PatientName))
        {
            messageStore.Add(editContext.Field(nameof(Model.PatientName)), "Patient name is required.");
            valid = false;
        }

        if (string.IsNullOrWhiteSpace(Model.Email))
        {
            messageStore.Add(editContext.Field(nameof(Model.Email)), "Email is required.");
            valid = false;
        }
        else if (!IsValidEmail(Model.Email))
        {
            messageStore.Add(editContext.Field(nameof(Model.Email)), "Invalid email format.");
            valid = false;
        }

        if (string.IsNullOrWhiteSpace(Model.Phone))
        {
            messageStore.Add(editContext.Field(nameof(Model.Phone)), "Phone is required.");
            valid = false;
        }

        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
        {
            messageStore.Add(editContext.Field(nameof(Model.InsuranceProvider)), "Insurance provider is required.");
            valid = false;
        }

        editContext.NotifyValidationStateChanged();

        if (valid)
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        availableSlots = [];
        Model.TimeSlot = "";
        availabilityChecked = false;

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        messageStore.Clear();
        var step2Valid = ValidateStep2Fields();

        editContext.NotifyValidationStateChanged();
        if (!step2Valid) return;

        var serverErrors = await AppointmentSvc.ValidatePatientAsync(
            Model.Email, Model.InsuranceProvider, Model.Doctor, Model.TimeSlot);

        if (serverErrors.Count > 0)
        {
            foreach (var (field, error) in serverErrors)
            {
                messageStore.Add(editContext.Field(field), error);
            }

            editContext.NotifyValidationStateChanged();
            return;
        }

        availabilityChecked = true;
    }

    private bool ValidateStep2Fields()
    {
        var valid = true;

        if (string.IsNullOrWhiteSpace(Model.Doctor))
        {
            messageStore.Add(editContext.Field(nameof(Model.Doctor)), "Please select a doctor.");
            valid = false;
        }

        if (!Model.AppointmentDate.HasValue)
        {
            messageStore.Add(editContext.Field(nameof(Model.AppointmentDate)),
                "Appointment date is required.");
            valid = false;
        }
        else if (Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            messageStore.Add(editContext.Field(nameof(Model.AppointmentDate)),
                "Date must be in the future.");
            valid = false;
        }

        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
        {
            messageStore.Add(editContext.Field(nameof(Model.TimeSlot)), "Please select a time slot.");
            valid = false;
        }

        if (string.IsNullOrWhiteSpace(Model.ReasonForVisit))
        {
            messageStore.Add(editContext.Field(nameof(Model.ReasonForVisit)),
                "Reason for visit is required.");
            valid = false;
        }
        else if (Model.ReasonForVisit.Length > 500)
        {
            messageStore.Add(editContext.Field(nameof(Model.ReasonForVisit)),
                "Reason must be 500 characters or fewer.");
            valid = false;
        }

        return valid;
    }

    private void HandleSubmit()
    {
        submitted = true;
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityChecked = false;
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}

